CREATE TABLE IF NOT EXISTS daily_menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140) NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'Acompanhamentos', active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lunch_settings (id TINYINT UNSIGNED PRIMARY KEY, price_cents INT UNSIGNED NOT NULL DEFAULT 2000, max_choices INT UNSIGNED NOT NULL DEFAULT 5, pix_enabled TINYINT(1) NOT NULL DEFAULT 1, card_enabled TINYINT(1) NOT NULL DEFAULT 1, orders_enabled TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT INTO lunch_settings(id,price_cents,max_choices,pix_enabled,card_enabled,orders_enabled) VALUES(1,2000,5,1,1,1) ON DUPLICATE KEY UPDATE id=id;
CREATE TABLE IF NOT EXISTS lunch_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(150) NOT NULL, customer_phone VARCHAR(24) NOT NULL, address VARCHAR(350) NOT NULL, neighborhood VARCHAR(120) NOT NULL, reference_point VARCHAR(350) NOT NULL, payment_method ENUM('pix','card') NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price_cents INT UNSIGNED NOT NULL, total_cents INT UNSIGNED NOT NULL, status ENUM('pending','accepted','preparing','out_for_delivery','delivered','cancelled') NOT NULL DEFAULT 'pending', payment_status ENUM('pending','paid') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lunch_order_boxes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, box_number INT UNSIGNED NOT NULL, FOREIGN KEY(order_id) REFERENCES lunch_orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lunch_order_choices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, box_id BIGINT UNSIGNED NOT NULL, menu_item_id INT UNSIGNED NULL, item_name VARCHAR(140) NOT NULL, FOREIGN KEY(box_id) REFERENCES lunch_order_boxes(id), FOREIGN KEY(menu_item_id) REFERENCES daily_menu_items(id) ON DELETE SET NULL) ENGINE=InnoDB;
